// Expects webhook body at $input.first().json.body (n8n Webhook node default).
// Contract: action_type, severity, event_id, company, rfqs[], contingency_actions[], policy_citations[].
const raw = $input.first().json || {};
const p = raw.body ?? raw; // tolerate test-posts that omit the {body:} wrapper
const fmt = n => Number(n || 0).toLocaleString('en-IN');
const eventId = p.event_id || `SCD-MANUAL-${Date.now().toString().slice(-6)}`;
const rfqDocs = (Array.isArray(p.rfqs) ? p.rfqs : []).map((r, i) => {
  const qty = Number(r.quantity || 0);
  const price = Number(r.unit_price_inr || 0);
  return {
    rfq_number: `${eventId}-RFQ${String(i + 1).padStart(2, '0')}`,
    to: r.supplier_email || `${r.supplier_id || 'unknown'}@supplier.example`,
    subject: `Urgent RFQ ${r.part_id || '?'} x ${fmt(qty)} - ${p.company || 'Aravalli Mobility Pvt Ltd'}`,
    body: `Dear ${r.supplier_name || r.supplier_id || 'Supplier'},\n\nPlease quote for ${fmt(qty)} units of ${r.part_id || '?'} ` +
      `for delivery within ${r.required_within_days ?? '?'} days (CIF Nhava Sheva / DAP Manesar). ` +
      `Quote validity 15 days; state lead time, MOQ and capacity commitment.\n\nReason: ${r.justification || 'per SOP-SC-014'}\n\nProcurement, ${p.company || 'Aravalli Mobility Pvt Ltd'}`,
    est_value_inr: Number(r.est_value_inr ?? qty * price)
  };
});
const total = rfqDocs.reduce((s, r) => s + Number(r.est_value_inr || 0), 0);
if (!['RFQ','CONTINGENCY_PLAN','MONITOR_ONLY'].includes(p.action_type)) {
  throw new Error(`Invalid action_type '${p.action_type}'. Must be RFQ | CONTINGENCY_PLAN | MONITOR_ONLY.`);
}
return [{ json: {
  status: 'RECEIVED',
  event_id: eventId,
  action_type: p.action_type || 'UNKNOWN',
  severity: p.severity || 'UNKNOWN',
  routed_for_approval_to: p.approval_authority || 'Head of Supply Chain Management',
  rfqs_generated: rfqDocs.length,
  total_rfq_value_inr: fmt(total),
  total_rfq_value_raw: total,
  rfq_documents: rfqDocs,
  contingency_plan: Array.isArray(p.contingency_actions) ? p.contingency_actions : [],
  citations_logged: Array.isArray(p.policy_citations) ? p.policy_citations.length : 0,
  processed_at: new Date().toISOString()
}}];
